import { useState } from 'react'
import { dispatch } from 'react-redux'
import { BotaãoSalvar, MainContainer, Titulo } from '../../styles'
import { Campo } from '../../styles'
import { Opcoes } from '../Formulario/styles'
import { Form } from './styles'


const Formulario = () => {
  const [titulo, setTitulo] = useState('')
  const [descricao, setDescricao] = useState('')

  return (
    <MainContainer>
      <Titulo>Nova tarefa</Titulo>
      <Form>
        <Campo type="text" placeholder="Titulo" />
        <Campo as="textarea" placeholder="Descrição da tarefa" />
        <Opcoes>
          <p>Prioridade</p>
          <input name="prioridade" type="radio" id="urgente" />{' '}
          <label htmlFor="urgente">Urgente</label>
          <input name="prioridade" type="radio" id="importante" />{' '}
          <label htmlFor="importante">Importante</label>
          <input name="prioridade" type="radio" id="normal" />{' '}
          <label htmlFor="normal">Normal</label>
        </Opcoes>
        <BotaãoSalvar type="submit">Cadastrar</BotaãoSalvar>
      </Form>
    </MainContainer>
  )
}

export default Formulario
